from dynamodb.entity.todo.todo_entity import TodoEntity
from dynamodb.entity.todo.todo_entity_repo import TodoEntityRepo, TodoQueryResponse
from dynamodb.entity.todo.todo_entity_service import TodoEntityService


class TodoService:

    entity_service = TodoEntityService(TodoEntityRepo())

    @staticmethod
    def find_all_todo_by_list_id(list_id: str) -> TodoQueryResponse:
        return TodoService.entity_service.find_all_todo_by_list_id(list_id=list_id)

    @staticmethod
    def put_todo(todo: TodoEntity) -> TodoEntity:
        return TodoService.entity_service.put_todo(todo)

    @staticmethod
    def update_todo(list_id: str, todo_id: str, updates: dict):
        return TodoService.entity_service.update_todo(list_id=list_id, todo_id=todo_id, updates=updates)
